content=dst/'content'; index=json.loads((content/'index.json').read_text())
pack=json.loads((dst/'pack.json').read_text());pack['version']='1.2.0';pack['engine']['min']='0.65.0';pack['credits']=['By Michael Robinson','MP20 authored race, class, specializations and attack style; temporary art pending MP39–40.']
(dst/'pack.json').write_text(json.dumps(pack,indent=2)+'\n')
# distinct race: racial passive grant and numeric resistance
race={'format':'maxxia-authored-race','formatVersion':1,'id':'bell:race:bellforged','record':{'id':'bell:race:bellforged','name':'Bellforged','description':'A bronze-resonant folk of the old cistern. Their conductive bodies favor Constitution and endure lightning, and their Chime Instinct travels with them between adventures.','attributeBonuses':{'CON':1},'resistances':{'lightning':15},'traits':['bell:trait:echo_blood'],'abilityGrants':[{'id':'bell:ability:chime_instinct','minLevel':1}]}}
class_obj={'format':'maxxia-authored-class','formatVersion':1,'id':'bell:class:echo_sentinel','record':{'id':'bell:class:echo_sentinel','name':'Echo Sentinel','primary':'DEX','hpBase':11,'hpGain':6,'casting':None,'spBase':0,'spGain':0,'spAttributeMultiplier':0,'role':'A precision-oriented resonant striker, distinct from the defensive Bellwarden.','features':'Uses Sonorous Needle as a DEX-based lightning attack; Echo Pulse consumes 2 Echoes to guard an ally or self. Two starting specializations shape the recruit.','equipmentTags':['melee:staff','melee:dagger','melee:mace','melee:general','ranged','shield','armor:light','armor:medium','accessory'],'traits':['bell:trait:soundcraft'],'preparedStyles':['bell:style:sonorous_needle','standard'],'styleDefinitions':[{'id':'bell:style:sonorous_needle','name':'Sonorous Needle','description':'A resonant DEX-based melee strike dealing lightning damage, ignoring 1 Defense; grows from 1d6 to 1d8 at the veteran milestone.','operation':'device','requiredTrait':'bell:trait:soundcraft','attackBonus':0,'attackBonusAtVeteran':1,'damageBonus':0,'damageBonusAtMilestone':1,'damageBonusAtMilestoneReplacesBase':False,'ignoreDefense':1,'damageType':'lightning','dice':'1d6','diceAtMilestone':None,'diceAtVeteran':'1d8','defenseBonus':0,'defenseAtVeteran':0}],'abilityGrants':[{'id':'bell:ability:echo_pulse','minLevel':1}],'creationChoices':[{'id':'watcher','name':'Watcher','description':'Favours careful defence with +1 CON and a shield at creation.','attributeBonuses':{'CON':1},'starterEquipment':{'offhand':'bell:item:resonant_buckler'}},{'id':'runner','name':'Runner','description':'Favours speed with +1 DEX and a quarterstaff at creation.','attributeBonuses':{'DEX':1},'starterEquipment':{'melee':'item_staff'}}]}}
instinct={'format':'maxxia-authored-ability','formatVersion':1,'id':'bell:ability:chime_instinct','record':{'id':'bell:ability:chime_instinct','name':'Chime Instinct','description':'Grants +1 Attack as a passive; Bellforged of any class inherit it.','context':'both','target':'self','operations':[],'activation':{'mode':'passive','classes':['bell:class:echo_sentinel'],'minLevel':1,'passive':{'attack':1,'defense':0}}}}
echo={'format':'maxxia-authored-ability','formatVersion':1,'id':'bell:ability:echo_pulse','record':{'id':'bell:ability:echo_pulse','name':'Echo Pulse','description':'Spend two Echoes and one normal combat action to gain two rounds of resonant warding.','context':'combat','target':'self','operations':[{'op':'condition','conditionId':'bell:condition:resonant_guard','duration':2}],'activation':{'mode':'active','classes':['bell:class:echo_sentinel'],'minLevel':1,'resource':{'id':'bell:pool:echoes','base':4,'perLevel':1,'maximum':8,'recovery':'rest'},'cost':{'id':'bell:pool:echoes','amount':2},'cooldown':{'clock':'rounds','amount':2}}}}
for filename,obj in [('race_bellforged.json',race),('class_echo_sentinel.json',class_obj),('ability_chime_instinct.json',instinct),('ability_echo_pulse.json',echo)]: (content/filename).write_text(json.dumps(obj,indent=2)+'\n')
