for d in [desc('bell:race:bellforged','race','race_bellforged.json',['bell:ability:chime_instinct']),desc('bell:class:echo_sentinel','class','class_echo_sentinel.json',['bell:ability:echo_pulse','bell:item:resonant_buckler']),desc('bell:ability:chime_instinct','ability','ability_chime_instinct.json',['bell:class:echo_sentinel']),desc('bell:ability:echo_pulse','ability','ability_echo_pulse.json',['bell:class:echo_sentinel','bell:condition:resonant_guard'])]:
 assert not any(e['id']==d['id'] for e in index['definitions']); index['definitions'].append(d)
